import{_ as t,o,c as a,a3 as d}from"./chunks/framework.cNy3aYYk.js";const h=JSON.parse('{"title":"Opportunities real-time board sync (1.3.0) — Production Readiness Audit","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Opportunities real-time board sync (1.3.0) — Production Readiness Audit | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/deployment/opportunities-realtime-board-sync-1-3-0-production-readiness"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Opportunities real-time board sync (1.3.0) — Production Readiness Audit | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/deployment/opportunities-realtime-board-sync-1-3-0-production-readiness"}]]},"headers":[],"relativePath":"deployment/opportunities-realtime-board-sync-1-3-0-production-readiness.md","filePath":"deployment/opportunities-realtime-board-sync-1-3-0-production-readiness.md","lastUpdated":1791474066000}'),n={name:"deployment/opportunities-realtime-board-sync-1-3-0-production-readiness.md"};function r(s,e,i,c,p,l){return o(),a("div",null,[...e[0]||(e[0]=[d(`<h1 id="opportunities-real-time-board-sync-1-3-0-—-production-readiness-audit" tabindex="-1">Opportunities real-time board sync (1.3.0) — Production Readiness Audit <a class="header-anchor" href="#opportunities-real-time-board-sync-1-3-0-—-production-readiness-audit" aria-label="Permalink to &quot;Opportunities real-time board sync (1.3.0) — Production Readiness Audit&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td><strong>Date</strong></td><td>2026-10-04</td></tr><tr><td><strong>Status</strong></td><td><strong>Go for production</strong> (merge/deploy remaining; live Reverb smoke deferred to staging)</td></tr><tr><td><strong>Scope</strong></td><td>Private board channel <code>tenant.{id}.opportunities.board</code> + <code>OpportunityCreated</code>/<code>OpportunityUpdated</code>/<code>OpportunityStageChanged</code>/<code>OpportunityAssigned</code>/<code>OpportunityDeleted</code> broadcasts; SPA debounce-invalidate hook; catalog <strong>opportunities 1.2.0 → 1.3.0</strong></td></tr><tr><td><strong>Companion</strong></td><td><a href="/developer-guide/opportunities">Opportunities developer guide</a> · <a href="/user-guide/opportunities-overview">Opportunities overview</a> · <a href="/deployment/leads-realtime-board-sync-1-8-0-production-readiness">Leads 1.8.0 readiness</a> (pattern source) · <a href="/changelog/">CHANGELOG</a></td></tr></tbody></table><hr><h2 id="executive-summary" tabindex="-1">Executive summary <a class="header-anchor" href="#executive-summary" aria-label="Permalink to &quot;Executive summary&quot;">​</a></h2><p>The Opportunities Kanban board now stays in sync across open tabs/users without a manual refresh. Backend fires five <code>ShouldBroadcastNow</code> events off the existing <code>OpportunityEventSubscriber</code> domain-event handlers onto a new private Reverb channel; the SPA joins that channel only while the board view is mounted and debounces invalidation of the board + stats queries so a burst of changes collapses into one refetch. The design deliberately mirrors the <strong>Leads 1.8.0 / Live Chat inbox invalidate pattern</strong> (refetch-on-signal) and explicitly avoids the <strong>Team Chat message-patching pattern</strong> (no per-card payload merging).</p><p><strong>Go / No-Go:</strong> <strong>Go</strong>.</p><table tabindex="0"><thead><tr><th>Gate</th><th>Result</th></tr></thead><tbody><tr><td>Platform freeze (no parallel realtime architecture; reuses <code>window.Echo</code>)</td><td><strong>Pass</strong></td></tr><tr><td>Channel auth: same tenant + <code>opportunities.view</code> (mirrors <code>LeadBoardChannel</code>)</td><td><strong>Pass</strong></td></tr><tr><td>Cross-tenant isolation</td><td><strong>Pass</strong> — different <code>tenantId</code> on the channel name is rejected by <code>OpportunityBoardChannel::join</code></td></tr><tr><td>Broadcasts fire on create / update / stage change / assign / delete</td><td><strong>Pass</strong></td></tr><tr><td><code>previous_stage_id</code> present on stage-changed payload</td><td><strong>Pass</strong></td></tr><tr><td><code>assigned_to</code> present on assigned payload (including unassign → <code>null</code>)</td><td><strong>Pass</strong></td></tr><tr><td>Broadcast failures never break opportunity writes (<code>SafeRealtimeBroadcast</code>)</td><td><strong>Pass</strong></td></tr><tr><td>Domain events stay separate from broadcast classes</td><td><strong>Pass</strong> — new <code>App\\Events\\Opportunity\\*Broadcast</code> namespace; existing <code>App\\Events\\Opportunity{Created,Updated,...}</code> untouched</td></tr><tr><td>Catalog migrate-only <strong>1.3.0</strong> + CatalogSeeder companion</td><td><strong>Pass</strong></td></tr><tr><td>SPA debounced invalidate (~200ms), board-view-only subscription</td><td><strong>Pass</strong></td></tr><tr><td>Pest coverage</td><td><strong>Pass</strong> — <code>OpportunityRealtimeBoardTest</code> (7 / 17 assertions) + <code>OpportunitiesModuleVersion130BumpTest</code> (bump + CatalogSeeder companion)</td></tr><tr><td>Security: cross-tenant isolation</td><td><strong>Pass</strong></td></tr><tr><td>Security: assignee-scoped board metadata (tenant-wide channel)</td><td><strong>Accepted</strong> — identical to Leads 1.8.0; payload is id-only and SPA ignores content (API refetch remains assignee-scoped)</td></tr></tbody></table><h2 id="what-shipped" tabindex="-1">What shipped <a class="header-anchor" href="#what-shipped" aria-label="Permalink to &quot;What shipped&quot;">​</a></h2><h3 id="backend" tabindex="-1">Backend <a class="header-anchor" href="#backend" aria-label="Permalink to &quot;Backend&quot;">​</a></h3><ul><li><code>app/Broadcasting/OpportunityBoardChannel.php</code> — private channel auth, same shape as <code>LeadBoardChannel</code> (tenant match + <code>opportunities.view</code>).</li><li><code>routes/channels.php</code> — registers <code>tenant.{tenantId}.opportunities.board</code>.</li><li><code>app/Events/Opportunity/OpportunityBoardBroadcastPayload.php</code> — shared payload builder (<code>action</code>, <code>opportunity_id</code>, <code>uuid</code>, <code>actor_id</code>, <code>stage_id</code>, optional <code>previous_stage_id</code> / <code>assigned_to</code>).</li><li><code>app/Events/Opportunity/Opportunity{Created,Updated,StageChanged,Assigned,Deleted}Broadcast.php</code> — <code>ShouldBroadcastNow</code>, each <code>broadcastAs()</code> matching the SPA&#39;s <code>.OpportunityXxx</code> listener name.</li><li><code>app/Listeners/OpportunityEventSubscriber.php</code> — each existing domain-event handler for create/update/stage/assign/delete now also fires the matching broadcast via <code>SafeRealtimeBroadcast::dispatch</code>.</li><li>Catalog: <code>database/migrations/2026_10_04_024500_bump_opportunities_module_to_1_3_0.php</code> (migrate-only, reversible) + <code>CatalogSeeder</code> <code>opportunities</code> version <strong>1.3.0</strong>.</li></ul><h3 id="frontend" tabindex="-1">Frontend <a class="header-anchor" href="#frontend" aria-label="Permalink to &quot;Frontend&quot;">​</a></h3><ul><li><code>src/hooks/use-opportunities-board-realtime.ts</code> — subscribes via shared <code>window.Echo</code>; listens for all five events; debounces (~200ms) invalidate of <code>QUERY_KEYS.opportunityBoard</code> + <code>QUERY_KEYS.opportunityStats</code>.</li><li><code>src/pages/opportunities/opportunities-page.tsx</code> — calls the hook with <code>enabled: viewMode === &#39;board&#39;</code>.</li><li><code>src/types/api.ts</code> — <code>OpportunityBoardRealtimePayload</code> type.</li></ul><h3 id="docs" tabindex="-1">Docs <a class="header-anchor" href="#docs" aria-label="Permalink to &quot;Docs&quot;">​</a></h3><ul><li>Opportunities user/developer guides updated; product roadmap; this readiness doc; CHANGELOG entry.</li></ul><h2 id="test-evidence" tabindex="-1">Test evidence <a class="header-anchor" href="#test-evidence" aria-label="Permalink to &quot;Test evidence&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>herd php artisan test --compact tests/Feature/Tenant/Opportunity/OpportunityRealtimeBoardTest.php</span></span>
<span class="line"><span>Tests: 7 passed (17 assertions)</span></span></code></pre></div><p>Covers: channel auth (owner / <code>opportunities.view</code> staff / no-permission staff / cross-tenant), <code>OpportunityCreatedBroadcast</code> on create, <code>OpportunityUpdatedBroadcast</code> on update, <code>OpportunityStageChangedBroadcast</code> with correct <code>previous_stage_id</code>, <code>OpportunityAssignedBroadcast</code> with the new assignee id, <code>OpportunityDeletedBroadcast</code> on delete, and that a thrown broadcast listener does not prevent the opportunity write from succeeding.</p><p><code>vendor/bin/pint --dirty --format agent</code> — pass.</p><h2 id="known-limitations-deferred" tabindex="-1">Known limitations / deferred <a class="header-anchor" href="#known-limitations-deferred" aria-label="Permalink to &quot;Known limitations / deferred&quot;">​</a></h2><ul><li>No Reverb broadcaster runs in CI; broadcast dispatch is verified via <code>Event::fake([...])</code> + <code>Event::assertDispatched(...)</code> rather than an end-to-end socket round-trip. A live Reverb smoke test on staging is recommended before/at go-live.</li><li>No dedicated Playwright realtime spec — same as Leads 1.8.0 / Live Chat.</li><li>Board cards still fully refetch on any board-relevant event (invalidate, not patch) — intentional.</li><li>Mobile Opportunities board realtime is out of scope (web Kanban only).</li><li><strong>Assignee-scoped channel metadata (accepted):</strong> Channel join is tenant + <code>opportunities.view</code> (same as Leads <code>leads.view</code>). Staff without <code>opportunities.assign</code> can receive tenant-wide board event metadata (<code>opportunity_id</code>, <code>uuid</code>, <code>stage_id</code>, <code>assigned_to</code>, <code>actor_id</code>) even though HTTP board/list remain assignee-scoped. Payload excludes names/amounts/notes; the SPA only invalidates queries and refetches through the scoped API. Closing this would require per-user channels or org-wide-only join — deferred unless product wants to diverge from Leads.</li></ul><h2 id="upgrade-staging-smoke" tabindex="-1">Upgrade &amp; staging smoke <a class="header-anchor" href="#upgrade-staging-smoke" aria-label="Permalink to &quot;Upgrade &amp; staging smoke&quot;">​</a></h2><ol><li><code>php artisan migrate --force</code> — catalog <code>opportunities</code> → <strong>1.3.0</strong> (do <strong>not</strong> <code>db:seed</code>).</li><li>Open the Opportunities board in two browser sessions (same tenant, both with <code>opportunities.view</code>). In session A, create a deal, move a card between stages, assign it, then delete it. Confirm session B&#39;s board + KPI strip update within ~1s without a manual refresh.</li><li>Confirm a user without <code>opportunities.view</code> cannot subscribe to <code>tenant.{id}.opportunities.board</code> (channel auth rejects).</li></ol><h2 id="rollback" tabindex="-1">Rollback <a class="header-anchor" href="#rollback" aria-label="Permalink to &quot;Rollback&quot;">​</a></h2><p>Roll back the catalog migration (<code>down()</code> → <strong>1.2.0</strong>) after rolling back application code. The new broadcast classes and channel are additive — no schema changes, so rollback is code-only plus the catalog version bump.</p>`,24)])])}const g=t(n,[["render",r]]);export{h as __pageData,g as default};
